async function listAudit(sql, opts = {}) {
	return (await sql.query(`select id, at, actor_kind, actor_label, action, target_type, target_id, detail
     from audit_log
     where ($1::text is null or action like $1 || '%')
       and ($2::bigint is null or id < $2)
     order by id desc
     limit $3`, [
		opts.action ?? null,
		opts.before ?? null,
		Math.min(opts.limit ?? 100, 500)
	])).map((r) => ({
		id: Number(r.id),
		at: r.at instanceof Date ? r.at.toISOString() : String(r.at),
		actorKind: r.actor_kind,
		actorLabel: r.actor_label ?? r.actor_kind,
		action: r.action,
		targetType: r.target_type,
		targetId: r.target_id,
		detail: flatDetail(typeof r.detail === "string" ? JSON.parse(r.detail) : r.detail ?? {})
	}));
}
function flatDetail(d) {
	const out = {};
	for (const [k, v] of Object.entries(d)) out[k] = v === null || typeof v === "string" || typeof v === "number" || typeof v === "boolean" ? v : JSON.stringify(v);
	return out;
}
//#endregion
export { audit as n, listAudit as r, AUDIT_ACTION_LABEL as t };
